// WPE Android's view library (Igalia, LGPL 2.1; see LICENSE.md), vendored from
// https://github.com/Igalia/wpe-android at 325410617 (wpewebkit 2.55.0.3), the
// release that matches the engine's upstream WebKit pin. Summit's changes are
// marked "Summit:". Native libraries and headers under src/main/jniLibs,
// src/main/assets and src/main/cpp/imported are generated by
// tools/android/stage-engine.sh and are not in git.
plugins {
  alias(libs.plugins.android.library)
}

android {
  namespace = "org.wpewebkit"
  compileSdk {
    version = release(37) { minorApiLevel = 1 }
  }
  ndkVersion = "30.0.16248370"

  defaultConfig {
    minSdk = 33
    testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    externalNativeBuild {
      cmake {
        arguments += listOf("-DANDROID_STL=c++_shared", "-DANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES=ON")
      }
    }
  }

  compileOptions {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
  }

  buildFeatures {
    aidl = true
  }

  externalNativeBuild {
    cmake {
      path = file("src/main/cpp/CMakeLists.txt")
    }
  }

  val abis = listOf("x86_64", "arm64-v8a").filter { file("src/main/jniLibs/$it").isDirectory }
  if (abis.isEmpty()) {
    logger.warn("wpeview: no engine libraries staged; run tools/android/stage-engine.sh first")
  } else {
    defaultConfig { ndk { abiFilters += abis } }
  }

  lint {
    lintConfig = file("lint.xml")
  }
}

dependencies {
  implementation(libs.androidx.annotation)
  androidTestImplementation(libs.androidx.test.runner)
  androidTestImplementation(libs.androidx.test.rules)
  androidTestImplementation(libs.androidx.test.ext.junit)
}
